    return model_registry


def get_quality_specs() -> Tuple[List[QualityDatasetSpec], float, Path]:
    tau_raw = os.environ.get("INFERENCE_BENCH_QUALITY_TAU", "0.95").strip()
    try:
        tau = float(tau_raw)
    except ValueError:
        tau = 0.95

    seed = _default_quality_seed()
